// SetStatus reports whether the order existed.
func (st *OrderStore) SetStatus(id, status string) (Order, bool) {
	st.mu.Lock()
	defer st.mu.Unlock()
	o, ok := st.items[id]
	if !ok {
		return Order{}, false
	}
	o.Status = status
	st.items[id] = o
	return o, true
