	// Check if order is pending
	if order.Status != orderPending {
		// Non-pending status
		writeError(w, http.StatusConflict, codeConflict, "order is not pending and cannot be cancelled")
		return
	}

	// Update the order to cancelled
	order.SetStatus(id, orderCancelled)

	// Return the updated order
	writeJSON(w, http.StatusOK, order)
}

