// Validation error for stock exceeded
type validationError struct{ Field string; Reason string }
func (e validationError) Error() string { return e.Field + ": " + e.Reason }

// Error codes used in the "code" field of every error response.
const (
	codeValidationFailed = "validation_failed"
	codeRejected         = "rejected"
)

type errorEnvelope struct{ Error apiError }
type apiError struct{ Code string; Message string }

func writeError(w http.ResponseWriter, status int, code, message string) {
	writeRaw(w, status, errorEnvelope{
		Error: apiError{
			Code: code,
			Message: message,
		},
	})
}

func writeRaw(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(v)
}

