package shop

import (
	"net/http"
	"sync"
)

const orderPending = "pending"
const orderPaid = "paid"
const orderCancelled = "cancelled"

type OrderItem struct {
	ProductID string `json:"product_id"`
	Quantity  int    `json:"quantity"`
}

type Order struct {
	ID         string      `json:"id"`
	UserID     string      `json:"user_id"`
	Items      []OrderItem `json:"items"`
	TotalCents int64       `json:"total_cents"`
	Status     string      `json:"status"`
}

type OrderStore struct {
	mu    sync.RWMutex
	items map[string]Order
	seq   int
}

func NewOrderStore() *OrderStore {
	return &OrderStore{items: make(map[string]Order)}
}

func (st *OrderStore) Create(o Order) Order {
	st.mu.Lock()
	defer st.mu.Unlock()
	st.seq++
	o.ID = formatID("ord", st.seq)
	o.Items = slices.Clone(o.Items)
	st.items[o.ID] = o
	return o
}

func (st *OrderStore) Get(id string) (Order, bool) {
	st.mu.RLock()
	defer st.mu.RUnlock()
	o, ok := st.items[id]
	return o, ok
}

func (st *OrderStore) SetStatus(id, status string) (Order, bool) {
	st.mu.Lock()
	defer st.mu.Unlock()
	o, ok := st.items[id]
	if !ok {
		return Order{}, false
	}
	o.Status = status
	st.items[id] = o
	return o, true
}

func (st *OrderStore) List() []Order {
	st.mu.RLock()
	defer st.mu.RUnlock()
	out := make([]Order, 0, len(st.items))
	for _, o := range st.items {
		out = append(out, o)
	}
	slices.SortFunc(out, func(a, b Order) int { return strings.Compare(a.ID, b.ID) })
	return out
}

