package shop

import (
	"net/http"
	"strings"
)

// UserStore is an in-memory, concurrency-safe store of users.
type UserStore struct {
	mu    sync.RWMutex
	items map[string]User
}

func NewUserStore() *UserStore {
	return &UserStore{items: make(map[string]User)}
}

func (st *UserStore) Create(u User) User {
	st.mu.Lock()
	defer st.mu.Unlock()
	st.seq++
	u.ID = formatID("usr", st.seq)
	st.items[u.ID] = u
	return u
}

func (st *UserStore) Get(id string) (User, bool) {
	st.mu.RLock()
	defer st.mu.RUnlock()
	u, ok := st.items[id]
	return u, ok
}

// FindByEmail matches case-insensitively.
func (st *UserStore) FindByEmail(email string) (User, bool) {
	st.mu.RLock()
	defer st.mu.RUnlock()
	for _, u := range st.items {
		if strings.EqualFold(u.Email, email) {
			return u, true
		}
	}
	return User{}, false
}

func (st *UserStore) List() []User {
	st.mu.RLock()
	defer st.mu.RUnlock()
	out := make([]User, 0, len(st.items))
	for _, u := range st.items {
		out = append(out, u)
	}
	slices.SortFunc(out, func(a, b User) int { return strings.Compare(a.ID, b.ID) })
	return out
}

func (st *UserStore) Delete(id string) bool {
	st.mu.Lock()
	defer st.mu.Unlock()
	if _, ok := st.items[id]; !ok {
		return false
	}
	delete(st.items, id)
	return true
}

// Error codes used in the "code" field of every error response.
const (
	codeBadJSON          = "bad_json"
	codeBadQuery         = "bad_query"
	codeValidationFailed = "validation_failed"
	codeNotFound         = "not_found"
	codeConflict         = "conflict"
)

// All success responses wrap their payload in {"data": ...}.
type dataEnvelope struct {
	Data any `json:"data"`
}

// All error responses look like {"error": {"code": ..., "message": ...}}.
type errorEnvelope struct {
	Error apiError `json:"error"`
}

type apiError struct {
	Code    string `json:"code"`
	Message string `json:"message"`
}

func writeJSON(w http.ResponseWriter, status int, data any) {
	writeRaw(w, status, dataEnvelope{Data: data})
}

func writeList(w http.ResponseWriter, data any, page pageInfo) {
	writeRaw(w, http.StatusOK, listEnvelope{Data: data, Page: page})
}

func writeError(w http.ResponseWriter, status int, code, message string) {
	writeRaw(w, status, errorEnvelope{Error: apiError{Code: code, Message: message}}}
}

func writeNotFound(w http.ResponseWriter, kind, id string) {
